/**
 * Query defines the gRPC querier service.
 *
 * Everything about a treasury is publicly readable — balances, commitments,
 * who holds which role, what the spending limits are, and how much of the
 * current period is already used. A treasury whose rules can be inspected by
 * anyone is the point: beneficiaries can verify their schedule without asking
 * permission, and third parties can audit disbursements without access.
 */
export interface Query {
  /** Params queries the parameters of the module. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** GetTreasury queries one treasury by id. */
  GetTreasury(request: QueryGetTreasuryRequest): Promise<QueryGetTreasuryResponse>;
  /** ListTreasury queries all treasuries. */
  ListTreasury(request: QueryAllTreasuryRequest): Promise<QueryAllTreasuryResponse>;
  /** TreasuryBalances reports total, locked and available amounts per denom. */
  TreasuryBalances(request: QueryTreasuryBalancesRequest): Promise<QueryTreasuryBalancesResponse>;
  /** GetLock queries one lock by id. */
  GetLock(request: QueryGetLockRequest): Promise<QueryGetLockResponse>;
  /** ListLock queries all locks. */
  ListLock(request: QueryAllLockRequest): Promise<QueryAllLockResponse>;
  /** LocksByTreasury queries the locks held by one treasury. */
  LocksByTreasury(request: QueryLocksByTreasuryRequest): Promise<QueryLocksByTreasuryResponse>;
  /**
   * LocksByBeneficiary queries the locks payable to one address, so a
   * beneficiary can find what is owed to them without knowing any treasury id.
   */
  LocksByBeneficiary(request: QueryLocksByBeneficiaryRequest): Promise<QueryLocksByBeneficiaryResponse>;
  /** ClaimableAmount reports what a lock would release if claimed right now. */
  ClaimableAmount(request: QueryClaimableAmountRequest): Promise<QueryClaimableAmountResponse>;
  /** ListRole queries the role assignments of one treasury. */
  ListRole(request: QueryListRoleRequest): Promise<QueryListRoleResponse>;
  /** GetSpendPolicy queries the spending policy for one treasury and denom. */
  GetSpendPolicy(request: QueryGetSpendPolicyRequest): Promise<QueryGetSpendPolicyResponse>;
  /** SpendCapacity reports how much may still be spent in the current period. */
  SpendCapacity(request: QuerySpendCapacityRequest): Promise<QuerySpendCapacityResponse>;
}

